package com.example.approval.adapter;
import com.example.approval.application.*; import com.example.approval.domain.*; import java.util.*;
/** Synchronized optimistic store. Defensive copies prevent alias-based mutation; this is not durable storage. */
public final class InMemoryExpenseRequestRepository implements ExpenseRequestRepository { private final Map<ExpenseRequestId,ExpenseRequest> rows=new HashMap<>(); public synchronized Optional<ExpenseRequest> findById(ExpenseRequestId id){return Optional.ofNullable(rows.get(id)).map(ExpenseRequest::copy);} public synchronized void saveNew(ExpenseRequest r){if(rows.containsKey(r.id()))throw new VersionConflictException("Request already exists: "+r.id().value());if(r.version()!=0)throw new VersionConflictException("New request must start at version zero");rows.put(r.id(),r.copy());} public synchronized void save(ExpenseRequest r,long expected){ExpenseRequest current=rows.get(r.id());if(current==null)throw new VersionConflictException("Cannot update missing request");if(current.version()!=expected)throw new VersionConflictException("Expected version "+expected+" but was "+current.version());if(r.version()!=expected+1)throw new VersionConflictException("Exactly one transition must be saved per command");rows.put(r.id(),r.copy());} }